--  confidence_score, model_version);
--
-- COMMIT;
-- SELECT CONCAT('Loaded ', ROW_COUNT(), ' predictions') AS Status;

-- ============================================================================
-- Re-enable constraints
-- ============================================================================
SET foreign_key_checks = 1;
SET unique_checks = 1;
SET autocommit = 1;

-- ============================================================================
-- Verify Data Loading
-- ============================================================================
SELECT 'Data Loading Summary' AS Report;
SELECT '===================' AS '';

SELECT
    'districts' AS table_name,
    COUNT(*) AS row_count
FROM districts
UNION ALL
SELECT 'bins', COUNT(*) FROM bins
UNION ALL
SELECT 'sensors', COUNT(*) FROM sensors
UNION ALL
SELECT 'collection_routes', COUNT(*) FROM collection_routes
UNION ALL
SELECT 'route_bin_assignments', COUNT(*) FROM route_bin_assignments
UNION ALL
SELECT 'trucks', COUNT(*) FROM trucks
UNION ALL
SELECT 'drivers', COUNT(*) FROM drivers
UNION ALL
SELECT 'collection_schedules', COUNT(*) FROM collection_schedules
UNION ALL
SELECT 'collection_events', COUNT(*) FROM collection_events
UNION ALL
SELECT 'sensor_readings', COUNT(*) FROM sensor_readings
UNION ALL
SELECT 'sensor_readings_hourly', COUNT(*) FROM sensor_readings_hourly
UNION ALL
SELECT 'sensor_readings_daily', COUNT(*) FROM sensor_readings_daily
UNION ALL
SELECT 'alert_thresholds', COUNT(*) FROM alert_thresholds
UNION ALL
SELECT 'alerts', COUNT(*) FROM alerts;

-- ============================================================================
-- Analyze Tables for Query Optimization
-- ============================================================================
ANALYZE TABLE districts;
ANALYZE TABLE bins;
ANALYZE TABLE sensors;
ANALYZE TABLE collection_routes;
ANALYZE TABLE route_bin_assignments;
ANALYZE TABLE trucks;
ANALYZE TABLE drivers;
ANALYZE TABLE collection_schedules;
ANALYZE TABLE collection_events;
ANALYZE TABLE sensor_readings;
ANALYZE TABLE sensor_readings_hourly;
ANALYZE TABLE sensor_readings_daily;
ANALYZE TABLE alert_thresholds;
ANALYZE TABLE alerts;

SELECT 'Data loaded and tables analyzed successfully' AS Status;
